import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Private Data","description":"","frontmatter":{"title":"Private Data"},"headers":[],"relativePath":"docs/privacy-and-security/private-data.md","filePath":"docs/privacy-and-security/private-data.md","lastUpdated":1794508483000}'),s={name:"docs/privacy-and-security/private-data.md"};function n(i,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="private-data" tabindex="-1">Private Data <a class="header-anchor" href="#private-data" aria-label="Permalink to &quot;Private Data&quot;">​</a></h1><p>Your statements, financial records and local-model analysis stay on your computer. Online services are separate choices: a cloud model, a web tool, a statement download, reporting or account activation has its own network behavior. Review <a href="/docs/settings/privacy">Privacy settings</a> to see what is enabled.</p><h2 id="personal-information" tabindex="-1">Personal information <a class="header-anchor" href="#personal-information" aria-label="Permalink to &quot;Personal information&quot;">​</a></h2><p>Names, addresses, account numbers and other details can identify you or reveal private information. OrbySystems masks account numbers to their last four digits in imported financial records. Passwords and access codes are secrets: do not include them in chat or support samples.</p><h2 id="local-storage" tabindex="-1">Local storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local storage&quot;">​</a></h2><h3 id="financial-statements-and-exports" tabindex="-1">Financial statements and exports <a class="header-anchor" href="#financial-statements-and-exports" aria-label="Permalink to &quot;Financial statements and exports&quot;">​</a></h3><p>OrbySystems keeps encrypted local copies of imported statements and exports, alongside the derived records used for analysis. Those copies support source citations and rereading even if you move the original file. An older import whose file was unavailable may still need you to locate the original.</p><p>Use <a href="/docs/settings/backup">backups</a> to protect your projects and documents. Local storage is not a substitute for a backup or for keeping important original records.</p><h3 id="general-documents" tabindex="-1">General documents <a class="header-anchor" href="#general-documents" aria-label="Permalink to &quot;General documents&quot;">​</a></h3><p>Document text and search indexes are kept locally so the app can retrieve relevant passages. If you choose a cloud embedding model, that provider receives the text it indexes. If you choose a cloud chat model, it receives your prompts and the context used to answer them. See <a href="/docs/privacy-and-security/trusted-vs-untrusted-models">Models and your data</a>.</p><h2 id="network-activity" tabindex="-1">Network activity <a class="header-anchor" href="#network-activity" aria-label="Permalink to &quot;Network activity&quot;">​</a></h2><ul><li><strong>Online tools</strong> send requests to the services you enable. A statement download connects the OrbySystems browser to your bank after you sign in yourself.</li><li><strong>Updates and activation</strong> contact the services needed to check releases or refresh device access.</li><li><strong>Usage reports</strong> follow the separate basic and enhanced reporting controls in Settings → Privacy. They do not include financial records or chat text.</li><li><strong>Support samples</strong> leave your computer only when you choose to send them. Review the privacy-protected sample before sharing it.</li><li><strong>Generated scripts</strong> use the restrictions described in <a href="/docs/privacy-and-security/sandboxing">Sandboxing</a>.</li></ul><p>Do not assume a cloud model&#39;s inputs are automatically anonymized. Personal information detection settings do not currently scrub ordinary chat messages before they reach your chosen provider.</p><h2 id="prepare-a-document-for-sharing" tabindex="-1">Prepare a document for sharing <a class="header-anchor" href="#prepare-a-document-for-sharing" aria-label="Permalink to &quot;Prepare a document for sharing&quot;">​</a></h2><p>Use the standalone <a href="/docs/tools/pii-redactor">PII Redactor</a> to prepare a copy with personal information removed. Review the result yourself before sharing it; detection can miss information.</p>',15)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
